67: /**
68:  * Validates the raw CUSTOM event payload carried by `app.inspection.result`.
69:  * Unknown detail fields are preserved so the copied error report stays complete.
70:  */
71: export function parseInspectionResult(data: unknown): InspectionParseResult {
72:   const result = inspectionResultSchema.safeParse(data);
73:   if (!result.success) return { ok: false };
74: 
75:   return {
76:     ok: true,
77:     value: {
78:       target: result.data.target,
79:       checks: result.data.checks.map((check) => {
80:         const normalizedStatus = check.status.trim().toLowerCase();
81:         return {
82:           name: check.name,
83:           status: check.status,
84:           passed: normalizedStatus === "passed",
85:           failed: normalizedStatus === "failed",
86:           detail: normalizeDetail(check.detail),
87:         };
88:       }),
89:     },
90:   };
91: }
